// Qwen2 pre-tokenizer vs. HF tokenizers reference splits
// (tests/tokenizer/pretokenize_reference.json, generated by make_reference.py).
#include <fstream>
#include <string>
#include <vector>
#include <nlohmann/json.hpp>
#include "check.h"
#include "tokenizer.h"

int main(int argc, char** argv) {
    if (argc < 2) { std::fprintf(stderr, "usage: test_tokenizer_pretokenize <reference.json>\n"); return 2; }
    std::ifstream f(argv[1]);
    if (!f) { std::fprintf(stderr, "cannot open %s\n", argv[1]); return 2; }
    const auto ref = nlohmann::json::parse(f);
    int cases = 0;
    for (const auto& c : ref) {
        const std::string text = c["text"];
        const auto expected = c["pieces"].get<std::vector<std::string>>();
        const auto got = Tokenizer::preTokenize(text);
        ++cases;
        if (got != expected) {
            std::fprintf(stderr, "mismatch for case %d (%zu pieces, expected %zu)\n", cases, got.size(), expected.size());
        }
        CHECK(got == expected);
    }
    std::printf("pre-tokenizer cases: %d\n", cases);
    return CHECK_RESULT();
}
